const MAX_LEN = 800;
const body = $json.body || $json;

const inputMessage = body.message ?? body.chatInput ?? body.query ?? '';
const raw = String(inputMessage).replace(/[\u0000-\u001F\u007F]/g, ' ').trim();

if (!raw) {
  throw new Error('Empty message received');
}

const cleaned = raw.slice(0, MAX_LEN);

return [{
  json: {
    sessionId: String(body.sessionId ?? '').slice(0, 64) || 'anon-' + Date.now(),
    message: cleaned,
    chatInput: cleaned,
    query: cleaned,
    contact: {
      name:  String(body.contactName  ?? '').slice(0, 120),
      email: String(body.contactEmail ?? '').slice(0, 160),
      phone: String(body.contactPhone ?? '').slice(0, 40)
    },
    market: String(body.market ?? 'IN').toUpperCase().slice(0, 2),
    locale: String(body.locale ?? 'en').slice(0, 5),
    pageUrl: String(body.pageUrl ?? '').slice(0, 500),
    consent: Boolean(body.consent),
    receivedAt: new Date().toISOString()
  }
}];
